const request = $input.first().json;

const headers = request.headers ?? {};
const rawContentType = String(
  headers['content-type'] ??
  headers['Content-Type'] ??
  ''
);

const contentType = rawContentType
  .split(';')[0]
  .trim()
  .toLowerCase();

const errors = [];

const isObject = (value) =>
  value !== null &&
  typeof value === 'object' &&
  !Array.isArray(value);

const has = (object, key) =>
  Object.prototype.hasOwnProperty.call(object, key);

const addError = (field, code) => {
  errors.push({ field, code });
};

const requiredString = (object, key, field) => {
  if (!has(object, key) || object[key] === null) {
    addError(field, 'required');
    return null;
  }

  if (typeof object[key] !== 'string') {
    addError(field, 'invalid_type');
    return null;
  }

  const value = object[key].trim();

  if (value === '') {
    addError(field, 'required');
    return null;
  }

  return value;
};

const optionalString = (object, key, field) => {
  if (!has(object, key) || object[key] === null) {
    return null;
  }

  if (typeof object[key] !== 'string') {
    addError(field, 'invalid_type');
    return null;
  }

  const value = object[key].trim();

  return value === '' ? null : value;
};

// Reject requests that are not JSON.
if (contentType !== 'application/json') {
  return [
    {
      json: {
        validation_ok: false,
        http_status: 415,
        response_body: {
          status: 'rejected',
          error_code: 'unsupported_media_type',
        },
      },
    },
  ];
}

const body = request.body;

// Body must be exactly one JSON object.
if (!isObject(body)) {
  return [
    {
      json: {
        validation_ok: false,
        http_status: 400,
        response_body: {
          status: 'rejected',
          error_code: 'invalid_payload',
          errors: [
            {
              field: 'body',
              code: 'invalid_type',
            },
          ],
        },
      },
    },
  ];
}

// Reject unknown top-level fields.
const allowedTopLevelFields = new Set([
  'event_type',
  'event_id',
  'deal_id',
  'company',
  'contact',
  'metadata',
]);

for (const key of Object.keys(body)) {
  if (!allowedTopLevelFields.has(key)) {
    addError(key, 'unsupported_field');
  }
}

const eventType = requiredString(
  body,
  'event_type',
  'event_type',
);

const eventId = requiredString(
  body,
  'event_id',
  'event_id',
);

const dealId = requiredString(
  body,
  'deal_id',
  'deal_id',
);

if (eventType !== null && eventType !== 'deal.won') {
  addError('event_type', 'invalid_value');
}

// Validate company.
let companyName = null;

if (!has(body, 'company')) {
  addError('company', 'required');
} else if (!isObject(body.company)) {
  addError('company', 'invalid_type');
} else {
  const allowedCompanyFields = new Set(['name']);

  for (const key of Object.keys(body.company)) {
    if (!allowedCompanyFields.has(key)) {
      addError(`company.${key}`, 'unsupported_field');
    }
  }

  companyName = requiredString(
    body.company,
    'name',
    'company.name',
  );
}

// Validate contact.
let contactFirstName = null;
let contactLastName = null;
let contactEmail = null;
let contactPhone = null;

if (!has(body, 'contact')) {
  addError('contact', 'required');
} else if (!isObject(body.contact)) {
  addError('contact', 'invalid_type');
} else {
  const allowedContactFields = new Set([
    'first_name',
    'last_name',
    'email',
    'phone',
  ]);

  for (const key of Object.keys(body.contact)) {
    if (!allowedContactFields.has(key)) {
      addError(`contact.${key}`, 'unsupported_field');
    }
  }

  contactFirstName = optionalString(
    body.contact,
    'first_name',
    'contact.first_name',
  );

  contactLastName = optionalString(
    body.contact,
    'last_name',
    'contact.last_name',
  );

  contactEmail = requiredString(
    body.contact,
    'email',
    'contact.email',
  );

  contactPhone = optionalString(
    body.contact,
    'phone',
    'contact.phone',
  );
}

// Validate metadata.
const normalizedMetadata = {};

if (has(body, 'metadata')) {
  if (!isObject(body.metadata)) {
    addError('metadata', 'invalid_type');
  } else {
    const allowedMetadataFields = new Set([
      'pipeline_id',
      'owner_id',
    ]);

    for (const key of Object.keys(body.metadata)) {
      if (!allowedMetadataFields.has(key)) {
        addError(`metadata.${key}`, 'unsupported_field');
        continue;
      }

      const value = body.metadata[key];

      if (value === null) {
        normalizedMetadata[key] = null;
        continue;
      }

      if (typeof value !== 'string') {
        addError(`metadata.${key}`, 'invalid_type');
        continue;
      }

      const normalizedValue = value.trim();

      normalizedMetadata[key] =
        normalizedValue === '' ? null : normalizedValue;
    }
  }
}

if (errors.length > 0) {
  return [
    {
      json: {
        validation_ok: false,
        http_status: 400,
        response_body: {
          status: 'rejected',
          error_code: 'invalid_payload',
          errors,
        },
      },
    },
  ];
}

// Return only sanitized and normalized values.
// Authorization headers are intentionally removed.
return [
  {
    json: {
      validation_ok: true,
      source_system: 'mock_crm',
      source_event_id: eventId,
      source_deal_id: dealId,
      intake_company_name: companyName,
      intake_contact_first_name: contactFirstName,
      intake_contact_last_name: contactLastName,
      intake_contact_email: contactEmail,
      intake_contact_phone: contactPhone,
      intake_metadata: {
        event_type: eventType,
        crm: normalizedMetadata,
      },
      source_intake_event_key:
        `crm:mock_crm:event:${eventId}:deal-won-received`,
    },
  },
];

